/// The catalog entry for a stored name, if it is still one of ours.
///
/// A name this does not know is not an error here: the identifier comes
/// over the wire and the catalog is this build's, so the two can disagree
/// the moment an action type outlives the category that admitted its icon
/// — DR-0014.
pub fn find(name: &str) -> Option<&'static Icon> {
    CATALOG
        .binary_search_by(|icon| icon.name.cmp(name))
        .ok()
        .map(|index| &CATALOG[index])
}
